 ("في الْقُطْبِ ❄️","ما الْحَيَوانُ الَّذي يَعيشُ في الْمَناطِقِ الْقُطْبِيَّةِ الْبارِدَةِ؟","نَموذَجٌ: الدُّبُّ الْقُطْبِيُّ وَالْفُقْمَةُ وَغَزالُ الرَّنَّةِ."),
 ("قِصَّةُ ديري 🗺️","التَّتابُعُ",[["🙈","الِاخْتِباءُ","لَعِبَ ديري مَعَ أَصْدِقائِهِ لُعْبَةَ الِاخْتِباءِ."],["🏃","الضَّياعُ","ابْتَعَدَ كَثيرًا، وَضاعَ في الْأَرْضِ الثَّلْجِيَّةِ."],["👣","الْعَوْدَةُ","تَبِعَ آثارَ أَقْدامِهِ الْقَديمَةَ، وَعادَ إِلى أَصْدِقائِهِ."]]),
 ("صِفَةُ الدُّبِّ الْقُطْبِيِّ ← جُزْؤُهُ 🔗",[["رَأْسٌ صَغيرٌ","الرَّأْسُ"],["فَرْوَةٌ ناعِمَةٌ","الْجِسْمُ"],["أَرْجُلٌ مُفَلْطَحَةٌ","لِلسِّباحَةِ وَالسَّيْرِ عَلى الثَّلْجِ"],["عُنُقٌ طَويلٌ","لِلْوُصولِ إِلى طَعامِهِ في الْماءِ"]]),
 ("كَيْفَ عادَ ديري؟ 🔢","خُطُواتُ الْحَلِّ",[["1️⃣","أَدْرَكَ أَنَّهُ ضاعَ","فَكَّرَ بِهُدوءٍ بَدَلًا مِنَ الذُّعْرِ."],["2️⃣","تَذَكَّرَ الْآثارَ","آثارُ أَقْدامِهِ في الثَّلْجِ."],["3️⃣","اتَّبَعَها","وَصَلَ إِلى أَصْدِقائِهِ سالِمًا."]]),
 ("مُفَلْطَحَةٌ","«أَرْجُلُ الدُّبِّ الْقُطْبِيِّ مُفَلْطَحَةٌ»",["(أ) عَريضَةٌ وَمُسَطَّحَةٌ","(ب) رَفيعَةٌ جِدًّا","(ج) طَويلَةٌ جِدًّا"],"(أ): مُفَلْطَحَةٌ: عَريضَةٌ وَمُسَطَّحَةٌ؛ تُساعِدُهُ عَلى السَّيْرِ عَلى الثَّلْجِ."),
 ("أُقارِنُ حَيَواناتِ الْمَزْرَعَةِ وَالْقُطْبِ 🗣️","حَيَوانُ الْمَزْرَعَةِ يَعيشُ في … ، أَمّا حَيَوانُ الْقُطْبِ فَيَعيشُ في …","نَموذَجٌ: حَيَوانُ الْمَزْرَعَةِ يَعيشُ في مَكانٍ دافِئٍ، أَمّا حَيَوانُ الْقُطْبِ فَيَعيشُ في الثَّلْجِ الْبارِدِ."),
 ("كَيْفَ وَجَدَ ديري طَريقَ الْعَوْدَةِ؟ 🤔",["(أ) تَبِعَ آثارَ أَقْدامِهِ في الثَّلْجِ","(ب) اتَّصَلَ بِوالِدَيْهِ","(ج) طارَ إِلى الْمَنْزِلِ"],"(أ): تَذَكَّرَ آثارَ أَقْدامِهِ وَاتَّبَعَها لِلْعَوْدَةِ."),
 dict(head="أُفَكِّرُ بِهُدوءٍ عِنْدَ الضَّياعِ",sana="إِذا ضِعْتُ، أُفَكِّرُ بِهُدوءٍ، وَلا أَفْزَعُ.",fact="لِلدُّبِّ الْقُطْبِيِّ فَرْوٌ سَميكٌ يَحْميهِ مِنَ الْبَرْدِ الشَّديدِ.",dilemma="ضِعْتُ عَنْ أُسْرَتي في مَكانٍ مُزْدَحِمٍ… ماذا أَفْعَلُ؟",model="أَبْقى في مَكاني، وَأَبْحَثُ عَنْ شُرْطِيٍّ أَوْ مُوَظَّفٍ لِمُساعَدَتي، كَما فَعَلَ ديري بِهُدوءٍ."),
